/* Map definition:
 * Type: BPF_MAP_TYPE_PERCPU_ARRAY
 * Key: __u32 (0)
 * Val: __u64 (packet_count)
 * Max entries: 1
 */
struct {
    __uint(type, BPF_MAP_TYPE_PERCPU_ARRAY);
    __uint(key_size, sizeof(__u32));
    __uint(value_size, sizeof(__u64));
    __uint(max_entries, 1);
} total_packet_counter SEC(".maps");

