int xdp_total_packets(struct xdp_md *ctx)
{
    __u32 key = 0;
    __u64 *counter;

    /* Lookup the per-CPU counter for key 0 */
    counter = bpf_map_lookup_elem(&total_packet_counter, &key, 0);
    if (counter) {
        /* Increment the counter if found */
        (*counter)++;
    }

    /* Return XDP_PASS for every packet */
    return XDP_PASS;
}

